class Book { private: int bookID, pageCount; bool isAvailable; std::string bookName, authorName, isbn, borrowerName; public: Book(int id, int pages, std::string name, std::string author, std::string isbnNum) : bookID(id), pageCount(pages), bookName(name), authorName(author), isbn(isbnNum), isAvailable(true), borrowerName("") {} void lendBook(std::string newBorrower_Name) { isAvailable = false; borrowerName = newBorrower_Name; std::time_t time_now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()); std::cout << "The book has lent to " << borrowerName << " successfully.\nTime: " << std::ctime(&time_now); } void showBookInfo() const { std::cout << "ID: " << bookID << "\nName: " << bookName << "\nAuthor: " << authorName << "\nPages: " << pageCount << "\nISBN: " << isbn << "\nStatus: " << (isAvailable ? "Available" : "Lent") << "\n"; } bool getAvailability() const { return isAvailable; } std::string getBookName() const { return bookName; } }; class User { private: int userID, borrowedBook_Count, punishmentPoints; std::string userName, borrowedBooks[5]; public: User(int id, std::string name) : userID(id), userName(name), borrowedBook_Count(0), punishmentPoints(0) { for (int i = 0; i < 5; i++) borrowedBooks[i] = "None"; } bool canBorrow() const { return borrowedBook_Count < 5; } void addBorrowedBook(std::string bName) { if (canBorrow()) borrowedBooks[borrowedBook_Count++] = bName; } void showUserCard() const { std::cout << "--- USER CARD ---\nID: " << userID << " | Name: " << userName << "\nPenalty Points: " << punishmentPoints << "\nBorrowed Books (" << borrowedBook_Count << "/5):\n"; for (int i = 0; i < borrowedBook_Count; i++) std::cout << "  - " << borrowedBooks[i] << "\n"; std::cout << "-----------------\n"; } std::string getUserName() const { return userName; } }; void generateInvoice(const User &user, const Book &book) { std::string fileName = user.getUserName() + "_Receipt.txt"; std::ofstream file(fileName); if (file.is_open()) { auto now = std::chrono::system_clock::now(); std::time_t time_now = std::chrono::system_clock::to_time_t(now); std::time_t time_return = std::chrono::system_clock::to_time_t(now + std::chrono::hours(24 * 15)); file << "====================================\n      PETROGRAD CITY LIBRARY        \n====================================\nTransaction Date: " << std::ctime(&time_now) << "Return Deadline:  " << std::ctime(&time_return) << "------------------------------------\nUser: " << user.getUserName() << "\nBook: " << book.getBookName() << "\n------------------------------------\n      Knowledge is for All!         \n====================================\n"; file.close(); std::cout << "Invoice generated: " << fileName << "\n"; } else std::cout << "Error: Could not create invoice file!\n"; } int main() { bettersyntax::print("Welcome to Petrograd City Library Terminal"); bettersyntax::sleep(1); User u1(1917, "Nikolai Aleksandrovich"); Book b1(1, 160, "The State and Revolution", "Vladimir Ilyich Lenin", "978-0140184471"); u1.showUserCard(); bettersyntax::sleep(1); b1.showBookInfo(); bettersyntax::sleep(1); if (u1.canBorrow() && b1.getAvailability()) { u1.addBorrowedBook(b1.getBookName()); b1.lendBook(u1.getUserName()); generateInvoice(u1, b1); } else std::cout << "Transaction failed: Limit reached or book unavailable.\n"; bettersyntax::print("\nOperation completed. Press Enter to exit..."); bettersyntax::input(); bettersyntax::clear(); return 0; }
